func (l *MMSLexer) Sempred(localctx antlr.RuleContext, ruleIndex, predIndex int) bool {
	switch ruleIndex {
	case 11:
		return l.COMMAND_Sempred(localctx, predIndex)

	default:
		panic("No registered predicate for: " + fmt.Sprint(ruleIndex))
	}
}

func (p *MMSLexer) COMMAND_Sempred(localctx antlr.RuleContext, predIndex int) bool {
	switch predIndex {
	case 0:
		return p.atLineStart()

	default:
		panic("No predicate with index: " + fmt.Sprint(predIndex))
	}
}
